import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { LandingPage } from './components/LandingPage';
import { VaultCreation } from './components/VaultCreation';
import { VaultAccess } from './components/VaultAccess';
import { VaultDashboard } from './components/VaultDashboard';
import { Vault } from './types';
import { StorageService } from './services/storageService';

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'create' | 'access' | 'dashboard'>('landing');
  const [activeVault, setActiveVault] = useState<Vault | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  // Initialize and check URL for direct vault access
  useEffect(() => {
    const init = async () => {
      const urlParams = new URLSearchParams(window.location.hash.split('?')[1]);
      const vaultId = urlParams.get('vaultId');

      if (vaultId) {
        setView('access');
      }
      setLoading(false);
    };
    init();
  }, []);

  const handleCreateSuccess = (vault: Vault) => {
    setActiveVault(vault);
    setView('dashboard');
  };

  const handleAccessSuccess = (vault: Vault) => {
    setActiveVault(vault);
    setView('dashboard');
  };

  const handleLogout = () => {
    setActiveVault(null);
    setView('landing');
    // Clear any hash
    window.location.hash = '';
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-500"></div>
      </div>
    );
  }

  return (
    <Layout activeVault={activeVault} onLogout={handleLogout}>
      {view === 'landing' && (
        <LandingPage 
          onCreateClick={() => setView('create')} 
          onAccessClick={() => setView('access')} 
        />
      )}
      {view === 'create' && (
        <VaultCreation 
          onSuccess={handleCreateSuccess} 
          onCancel={() => setView('landing')} 
        />
      )}
      {view === 'access' && (
        <VaultAccess 
          onSuccess={handleAccessSuccess} 
          onCancel={() => setView('landing')} 
        />
      )}
      {view === 'dashboard' && activeVault && (
        <VaultDashboard 
          vault={activeVault} 
          onVaultUpdate={(v) => setActiveVault(v)}
          onExit={handleLogout}
        />
      )}
    </Layout>
  );
};

export default App;

