import React, { useState } from 'react';
import { ArrowLeft, Loader2, Sparkles, Clock } from 'lucide-react';
import { ExpiryOption, Vault } from '../types';
import { StorageService } from '../services/storageService';
import { AuthService } from '../services/authService';

interface VaultCreationProps {
  onSuccess: (vault: Vault) => void;
  onCancel: () => void;
}

export const VaultCreation: React.FC<VaultCreationProps> = ({ onSuccess, onCancel }) => {
  const [username, setUsername] = useState('');
  const [pin, setPin] = useState('');
  const [vaultName, setVaultName] = useState('');
  const [expiry, setExpiry] = useState<ExpiryOption>(ExpiryOption.ONE_DAY);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (username.length < 3) return setError('Username too short (min 3 chars)');
    if (pin.length < 4 || pin.length > 6) return setError('PIN must be 4-6 digits');
    if (!/^\d+$/.test(pin)) return setError('PIN must be numeric only');

    setLoading(true);
    try {
      const pinHash = await AuthService.hashPin(pin);
      const newVault = await StorageService.createVault({
        username,
        vaultName,
        pinHash,
        expiry
      });
      onSuccess(newVault);
    } catch (err: any) {
      setError(err.message || 'Failed to create vault');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto animate-in slide-in-from-bottom-8 duration-500">
      <button 
        onClick={onCancel}
        className="flex items-center gap-2 text-slate-400 hover:text-white mb-8 transition-colors"
      >
        <ArrowLeft className="w-4 h-4" /> Back to home
      </button>

      <div className="glass-card p-8 rounded-3xl shadow-2xl">
        <div className="mb-8 text-center">
          <div className="inline-flex p-3 bg-indigo-500/10 rounded-2xl mb-4">
            <Sparkles className="w-8 h-8 text-indigo-500" />
          </div>
          <h2 className="text-2xl font-bold text-white">Create Your Vault</h2>
          <p className="text-slate-400 text-sm mt-1">Set up your secure space in seconds</p>
        </div>

        <form onSubmit={handleCreate} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">Unique Username</label>
            <input 
              type="text"
              required
              placeholder="e.g. shadow_ninja"
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-white"
              value={username}
              onChange={(e) => setUsername(e.target.value.toLowerCase().replace(/\s/g, ''))}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">Security PIN</label>
              <input 
                type="password"
                required
                maxLength={6}
                placeholder="4-6 digits"
                className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-white tracking-widest text-center text-lg"
                value={pin}
                onChange={(e) => setPin(e.target.value.replace(/\D/g, ''))}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">Vault Name (Optional)</label>
              <input 
                type="text"
                placeholder="Private Pics"
                className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-white"
                value={vaultName}
                onChange={(e) => setVaultName(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
              <Clock className="w-4 h-4" /> Auto-Delete After
            </label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { label: '24 Hours', value: ExpiryOption.ONE_DAY },
                { label: '7 Days', value: ExpiryOption.SEVEN_DAYS },
                { label: '30 Days', value: ExpiryOption.THIRTY_DAYS },
              ].map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => setExpiry(opt.value)}
                  className={`py-2 px-1 text-xs rounded-lg border transition-all ${
                    expiry === opt.value 
                    ? 'bg-indigo-600 border-indigo-500 text-white font-semibold' 
                    : 'bg-slate-900 border-slate-700 text-slate-400 hover:border-slate-500'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded-xl text-sm text-center">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-600/50 py-4 rounded-xl font-bold text-white transition-all flex items-center justify-center gap-2"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Initialize Vault'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Loader2, Key, Unlock } from 'lucide-react';
import { Vault } from '../types';
import { StorageService } from '../services/storageService';
import { AuthService } from '../services/authService';

interface VaultAccessProps {
  onSuccess: (vault: Vault) => void;
  onCancel: () => void;
}

export const VaultAccess: React.FC<VaultAccessProps> = ({ onSuccess, onCancel }) => {
  const [username, setUsername] = useState('');
  const [pin, setPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Extract Vault ID from hash if available
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.hash.split('?')[1]);
    const vaultId = urlParams.get('vaultId');
    if (vaultId) {
      // If we have a vaultId, we search by that first
      StorageService.getVaultById(vaultId).then(v => {
        if (v) setUsername(v.username);
      });
    }
  }, []);

  const handleAccess = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!username) return setError('Username is required');
    if (!pin) return setError('PIN is required');

    setLoading(true);
    try {
      const vault = await StorageService.getVaultByUsername(username);
      if (!vault) throw new Error('Vault not found');

      if (vault.isEmergencyLocked) {
        throw new Error('This vault has been emergency locked');
      }

      const isValid = await AuthService.verifyPin(pin, vault.pinHash);
      if (!isValid) {
        await StorageService.incrementFailedAttempts(vault.id);
        throw new Error('Invalid PIN');
      }

      // Success
      await StorageService.resetFailedAttempts(vault.id);
      onSuccess(vault);
    } catch (err: any) {
      setError(err.message || 'Access failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto animate-in slide-in-from-bottom-8 duration-500">
      <button 
        onClick={onCancel}
        className="flex items-center gap-2 text-slate-400 hover:text-white mb-8 transition-colors"
      >
        <ArrowLeft className="w-4 h-4" /> Back to home
      </button>

      <div className="glass-card p-8 rounded-3xl shadow-2xl">
        <div className="mb-8 text-center">
          <div className="inline-flex p-3 bg-indigo-500/10 rounded-2xl mb-4">
            <Key className="w-8 h-8 text-indigo-500" />
          </div>
          <h2 className="text-2xl font-bold text-white">Unlock Vault</h2>
          <p className="text-slate-400 text-sm mt-1">Enter credentials to proceed</p>
        </div>

        <form onSubmit={handleAccess} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">Username</label>
            <input 
              type="text"
              required
              placeholder="Your username"
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-white"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">Vault PIN</label>
            <input 
              type="password"
              required
              maxLength={6}
              placeholder="••••••"
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-white tracking-widest text-center text-lg font-mono"
              value={pin}
              onChange={(e) => setPin(e.target.value.replace(/\D/g, ''))}
            />
          </div>

          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded-xl text-sm text-center">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-600/50 py-4 rounded-xl font-bold text-white transition-all flex items-center justify-center gap-2"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : (
              <>
                <Unlock className="w-5 h-5" />
                Access Vault
              </>
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Upload, Download, Share2, Eye, EyeOff, Trash2, 
  AlertTriangle, Settings, Grid, List, Check, Copy,
  Plus, X, FileArchive, Loader2
} from 'lucide-react';
import JSZip from 'jszip';
import { Vault, VaultImage } from '../types';
import { MAX_FILE_SIZE, ICONS } from '../constants';
import { StorageService } from '../services/storageService';
import { TelegramService } from '../services/telegramService';
import { ImageCard } from './ImageCard';

interface VaultDashboardProps {
  vault: Vault;
  onVaultUpdate: (vault: Vault) => void;
  onExit: () => void;
}

export const VaultDashboard: React.FC<VaultDashboardProps> = ({ vault, onVaultUpdate, onExit }) => {
  const [uploading, setUploading] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [zipLoading, setZipLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    try {
      const updatedImages = [...vault.images];

      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.size > MAX_FILE_SIZE) {
          alert(`File ${file.name} exceeds 20MB limit`);
          continue;
        }

        // 1. Upload to Telegram
        const tgResult = await TelegramService.uploadImage(file);

        // 2. Add to Vault metadata
        const newImage: VaultImage = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          mimeType: file.type,
          telegramFileId: tgResult.file_id,
          uploadedAt: Date.now(),
          url: URL.createObjectURL(file) // For instant UI feedback
        };
        updatedImages.push(newImage);
      }

      const updatedVault = await StorageService.updateVaultImages(vault.id, updatedImages);
      onVaultUpdate(updatedVault);
    } catch (err) {
      console.error(err);
      alert('Upload failed. Please try again.');
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleToggleViewOnly = async () => {
    const updated = await StorageService.updateVaultSettings(vault.id, { isViewOnly: !vault.isViewOnly });
    onVaultUpdate(updated);
  };

  const handleEmergencyLock = async () => {
    if (confirm('EMERGENCY: This will permanently lock access until manual recovery (if available). Proceed?')) {
      await StorageService.updateVaultSettings(vault.id, { isEmergencyLocked: true });
      onExit();
    }
  };

  const handleCopyLink = () => {
    const link = `${window.location.origin}${window.location.pathname}#?vaultId=${vault.id}`;
    navigator.clipboard.writeText(link);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const downloadAllAsZip = async () => {
    if (vault.images.length === 0) return;
    setZipLoading(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder("snapsave-images");

      for (const img of vault.images) {
        // Fetch from Telegram (simulated or proxy)
        const response = await fetch(img.url);
        const blob = await response.blob();
        folder?.file(img.name, blob);
      }

      const content = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `SnapSave_${vault.vaultName || vault.username}.zip`;
      a.click();
    } catch (err) {
      alert('ZIP generation failed');
    } finally {
      setZipLoading(false);
    }
  };

  const deleteVault = async () => {
    if (confirm('Are you sure you want to PERMANENTLY delete this vault and all its images?')) {
      await StorageService.deleteVault(vault.id);
      onExit();
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 bg-slate-900/40 p-6 rounded-3xl border border-slate-800">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-bold text-white">{vault.vaultName || "My SnapSave Vault"}</h2>
            <span className="px-2 py-1 bg-indigo-500/20 text-indigo-400 text-[10px] font-bold uppercase rounded tracking-wider">
              {vault.expiry === '24h' ? '24H AUTO-EXPIRY' : vault.expiry === '7d' ? '7D AUTO-EXPIRY' : '30D AUTO-EXPIRY'}
            </span>
          </div>
          <p className="text-slate-400 flex items-center gap-2">
            Username: <span className="text-slate-200 font-mono">{vault.username}</span>
            <span className="text-slate-600">|</span>
            ID: <span className="text-slate-200 font-mono">{vault.id}</span>
          </p>
        </div>

        <div className="flex flex-wrap gap-3">
          <button 
            onClick={handleCopyLink}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl transition-all border border-slate-700"
          >
            {copySuccess ? <Check className="w-4 h-4 text-green-400" /> : <Share2 className="w-4 h-4" />}
            {copySuccess ? 'Copied' : 'Share Link'}
          </button>

          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`p-2 rounded-xl transition-all border ${showSettings ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white'}`}
          >
            <Settings className="w-5 h-5" />
          </button>

          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-indigo-500/20 disabled:bg-indigo-800 transition-all"
          >
            {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
            Upload Snaps
          </button>
          <input 
            type="file" 
            multiple 
            accept="image/jpeg,image/png,image/webp"
            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
        </div>
      </div>

      {/* Settings Panel */}
      {showSettings && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-in slide-in-from-top-4 duration-300">
          <button 
            onClick={handleToggleViewOnly}
            className="flex items-center justify-between p-4 bg-slate-900/60 rounded-2xl border border-slate-800 hover:border-indigo-500/50 transition-all"
          >
            <div className="flex items-center gap-3">
              {vault.isViewOnly ? <EyeOff className="text-orange-400" /> : <Eye className="text-indigo-400" />}
              <div className="text-left">
                <p className="text-sm font-semibold text-white">View-Only Mode</p>
                <p className="text-[10px] text-slate-500">Disables image downloads</p>
              </div>
            </div>
