    </div>
  );
};

import bcrypt from 'bcryptjs';

/**
 * Service to handle PIN hashing and verification using bcrypt.
 * In a real-world scenario, hashing would happen on the server.
 */
export const AuthService = {
  /**
   * Hashes a 4-6 digit PIN.
   */
  async hashPin(pin: string): Promise<string> {
    const salt = await bcrypt.genSalt(10);
    return bcrypt.hash(pin, salt);
  },

  /**
   * Verifies a PIN against a hash.
   */
  async verifyPin(pin: string, hash: string): Promise<boolean> {
    return bcrypt.compare(pin, hash);
  }
};

import { Vault, ExpiryOption, VaultImage } from '../types';

const STORAGE_KEY = 'snapsave_vaults_db';

/**
 * Service to manage vault persistence.
 * Mimics a backend API with database operations.
 */
export const StorageService = {
  _getDB(): Vault[] {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  _saveDB(vaults: Vault[]) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(vaults));
  },

  async createVault(params: {
    username: string;
    vaultName: string;
    pinHash: string;
    expiry: ExpiryOption;
  }): Promise<Vault> {
    const vaults = this._getDB();

    if (vaults.some(v => v.username === params.username)) {
      throw new Error('Username already taken');
    }

    const newVault: Vault = {
      id: Math.random().toString(36).substr(2, 12).toUpperCase(),
      username: params.username,
      vaultName: params.vaultName,
      pinHash: params.pinHash,
      images: [],
      createdAt: Date.now(),
      expiry: params.expiry,
      isEmergencyLocked: false,
      failedAttempts: 0,
      isViewOnly: false
    };

    vaults.push(newVault);
    this._saveDB(vaults);
    return newVault;
  },

  async getVaultByUsername(username: string): Promise<Vault | null> {
    const vaults = this._getDB();
    return vaults.find(v => v.username === username) || null;
  },

  async getVaultById(id: string): Promise<Vault | null> {
    const vaults = this._getDB();
    return vaults.find(v => v.id === id) || null;
  },

  async updateVaultImages(id: string, images: VaultImage[]): Promise<Vault> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) throw new Error('Vault not found');

    vaults[index].images = images;
    this._saveDB(vaults);
    return vaults[index];
  },

  async updateVaultSettings(id: string, updates: Partial<Vault>): Promise<Vault> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) throw new Error('Vault not found');

    vaults[index] = { ...vaults[index], ...updates };
    this._saveDB(vaults);
    return vaults[index];
  },

  async incrementFailedAttempts(id: string): Promise<number> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) return 0;

    vaults[index].failedAttempts += 1;
    if (vaults[index].failedAttempts >= 5) {
      vaults[index].isEmergencyLocked = true;
    }
    this._saveDB(vaults);
    return vaults[index].failedAttempts;
  },

  async resetFailedAttempts(id: string) {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index !== -1) {
      vaults[index].failedAttempts = 0;
      this._saveDB(vaults);
    }
  },

  async deleteVault(id: string) {
    const vaults = this._getDB();
    const filtered = vaults.filter(v => v.id !== id);
    this._saveDB(filtered);
  }
};

import { TG_BOT_TOKEN, TG_CHAT_ID } from '../constants';

/**
 * Service to handle image uploads to Telegram.
 * In a real app, the token and chat ID should remain on the backend.
 */
export const TelegramService = {
  /**
   * Uploads a file to a Telegram chat via the Bot API.
   * Returns metadata including the file_id.
   */
  async uploadImage(file: File): Promise<{ file_id: string }> {
    const formData = new FormData();
    formData.append('chat_id', TG_CHAT_ID);
    formData.append('document', file);

    try {
      const response = await fetch(`https://api.telegram.org/bot${TG_BOT_TOKEN}/sendDocument`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!data.ok) {
        throw new Error(data.description || 'Telegram upload failed');
      }

      // Extract file_id from document part of response
      const fileId = data.result.document.file_id;
      return { file_id: fileId };
    } catch (error) {
      console.error('Telegram API Error:', error);
      throw error;
    }
  },

  /**
   * Note: In a production SnapSave, images would be served by a backend 
   * that fetches them from Telegram using getFile and then streams the 
   * bytes securely to the authenticated user.
   */
  async getImageUrl(fileId: string): Promise<string> {
    // This part normally requires server-side fetching because
