interface ImageCardProps {
  image: VaultImage;
  isViewOnly: boolean;
  onDelete: () => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ image, isViewOnly, onDelete }) => {
  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  const handleDownload = () => {
    if (isViewOnly) return;
    const a = document.createElement('a');
    a.href = image.url;
    a.download = image.name;
    a.click();
  };

  return (
    <div className="group relative bg-slate-900 rounded-2xl overflow-hidden border border-slate-800 hover:border-indigo-500/50 transition-all shadow-lg">
      {/* Image Preview */}
      <div className="aspect-square w-full overflow-hidden bg-slate-950">
        <img 
          src={image.url} 
          alt={image.name} 
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
        />

        {/* Hover Overlays */}
        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
          {!isViewOnly && (
            <button 
              onClick={handleDownload}
              className="p-3 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-md transition-all hover:scale-110"
              title="Download"
            >
              <Download className="w-5 h-5" />
            </button>
          )}
          <button 
            onClick={() => window.open(image.url, '_blank')}
            className="p-3 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-md transition-all hover:scale-110"
            title="Full View"
          >
            <Maximize2 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => { if(confirm('Delete snap?')) onDelete(); }}
            className="p-3 bg-red-500/20 hover:bg-red-500/40 text-red-400 rounded-full backdrop-blur-md transition-all hover:scale-110"
            title="Delete"
          >
            <Trash2 className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Footer Info */}
      <div className="p-3">
        <div className="flex items-center gap-2 mb-1">
          <FileText className="w-3 h-3 text-slate-500" />
          <h4 className="text-sm font-medium text-slate-200 truncate flex-1" title={image.name}>
            {image.name}
          </h4>
        </div>
        <div className="flex justify-between items-center text-[10px] text-slate-500 uppercase font-semibold">
          <span>{formatSize(image.size)}</span>
          <span>{new Date(image.uploadedAt).toLocaleDateString()}</span>
        </div>
      </div>
    </div>
  );
};

import { Vault, ExpiryOption, VaultImage } from '../types.ts';

const STORAGE_KEY = 'snapsave_vaults_db';

/**
 * Service to manage vault persistence.
 * Mimics a backend API with database operations.
 */
export const StorageService = {
  _getDB(): Vault[] {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  _saveDB(vaults: Vault[]) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(vaults));
  },

  async createVault(params: {
    username: string;
    vaultName: string;
    pinHash: string;
    expiry: ExpiryOption;
  }): Promise<Vault> {
    const vaults = this._getDB();

    if (vaults.some(v => v.username === params.username)) {
      throw new Error('Username already taken');
    }

    const newVault: Vault = {
      id: Math.random().toString(36).substr(2, 12).toUpperCase(),
      username: params.username,
      vaultName: params.vaultName,
      pinHash: params.pinHash,
      images: [],
      createdAt: Date.now(),
      expiry: params.expiry,
      isEmergencyLocked: false,
      failedAttempts: 0,
      isViewOnly: false
    };

    vaults.push(newVault);
    this._saveDB(vaults);
    return newVault;
  },

  async getVaultByUsername(username: string): Promise<Vault | null> {
    const vaults = this._getDB();
    return vaults.find(v => v.username === username) || null;
  },

  async getVaultById(id: string): Promise<Vault | null> {
    const vaults = this._getDB();
    return vaults.find(v => v.id === id) || null;
  },

  async updateVaultImages(id: string, images: VaultImage[]): Promise<Vault> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) throw new Error('Vault not found');

    vaults[index].images = images;
    this._saveDB(vaults);
    return vaults[index];
  },

  async updateVaultSettings(id: string, updates: Partial<Vault>): Promise<Vault> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) throw new Error('Vault not found');

    vaults[index] = { ...vaults[index], ...updates };
    this._saveDB(vaults);
    return vaults[index];
  },

  async incrementFailedAttempts(id: string): Promise<number> {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index === -1) return 0;

    vaults[index].failedAttempts += 1;
    if (vaults[index].failedAttempts >= 5) {
      vaults[index].isEmergencyLocked = true;
    }
    this._saveDB(vaults);
    return vaults[index].failedAttempts;
  },

  async resetFailedAttempts(id: string) {
    const vaults = this._getDB();
    const index = vaults.findIndex(v => v.id === id);
    if (index !== -1) {
      vaults[index].failedAttempts = 0;
      this._saveDB(vaults);
    }
  },

  async deleteVault(id: string) {
    const vaults = this._getDB();
    const filtered = vaults.filter(v => v.id !== id);
    this._saveDB(filtered);
  }
};

import { TG_BOT_TOKEN, TG_CHAT_ID } from '../constants.tsx';

/**
 * Service to handle image uploads to Telegram.
 * In a real app, the token and chat ID should remain on the backend.
 */
export const TelegramService = {
  /**
   * Uploads a file to a Telegram chat via the Bot API.
   * Returns metadata including the file_id.
   */
  async uploadImage(file: File): Promise<{ file_id: string }> {
    const formData = new FormData();
    formData.append('chat_id', TG_CHAT_ID);
    formData.append('document', file);

    try {
      const response = await fetch(`https://api.telegram.org/bot${TG_BOT_TOKEN}/sendDocument`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!data.ok) {
        throw new Error(data.description || 'Telegram upload failed');
      }

      // Extract file_id from document part of response
      const fileId = data.result.document.file_id;
      return { file_id: fileId };
    } catch (error) {
      console.error('Telegram API Error:', error);
      throw error;
    }
  },

  /**
   * Note: In a production SnapSave, images would be served by a backend 
   * that fetches them from Telegram using getFile and then streams the 
   * bytes securely to the authenticated user.
   */
  async getImageUrl(fileId: string): Promise<string> {
