            <PlusCircle className="w-32 h-32" />
          </div>
          <PlusCircle className={`w-10 h-10 mb-4 ${termsAccepted ? 'text-white' : 'text-slate-500'}`} />
          <h3 className={`text-2xl font-bold mb-2 ${termsAccepted ? 'text-white' : 'text-slate-400'}`}>Create New Vault</h3>
          <p className={termsAccepted ? 'text-indigo-100/70' : 'text-slate-600'}>Start fresh. Set your unique username and a private PIN to secure your images instantly.</p>
        </button>

        <button 
          onClick={onAccessClick}
          disabled={!termsAccepted}
          className={`group relative overflow-hidden p-8 rounded-3xl transition-all duration-300 transform text-left border shadow-xl ${
            termsAccepted 
            ? 'bg-slate-800 hover:bg-slate-700 hover:-translate-y-1 border-slate-700' 
            : 'bg-slate-900/50 opacity-40 grayscale border-slate-800 cursor-not-allowed'
          }`}
        >
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <Key className="w-32 h-32" />
          </div>
          <Key className={`w-10 h-10 mb-4 ${termsAccepted ? 'text-indigo-400' : 'text-slate-600'}`} />
          <h3 className={`text-2xl font-bold mb-2 ${termsAccepted ? 'text-white' : 'text-slate-400'}`}>Access Existing Vault</h3>
          <p className="text-slate-500">Already have a vault? Enter your credentials or use a shareable link to view your saved snaps.</p>
